#!/usr/bin/env python3
"""GMRI private, authenticated, paginated SQLite graph explorer server.

Standard library only. No external analytics, CDNs, upload, model or telemetry.
Default bind is loopback. Public/LAN bind requires HTTPS certificate.
"""
from __future__ import annotations
import argparse
import hmac
import json
import re
import secrets
import sqlite3
import ssl
import sys
import time
from collections import deque
from http.server import ThreadingHTTPServer,BaseHTTPRequestHandler
from pathlib import Path
from urllib.parse import parse_qs,urlsplit

BASE=Path(__file__).resolve().parent
MIME={'/':'text/html; charset=utf-8','/app.js':'application/javascript; charset=utf-8','/style.css':'text/css; charset=utf-8'}
CSP="default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; frame-ancestors 'none'; form-action 'self'"


def _limit(q,key,default=50,maxval=500):
    try:v=int(q.get(key,[str(default)])[0])
    except (ValueError,TypeError):v=default
    return max(0,min(maxval,v))


def _connect(db):
    c=sqlite3.connect('file:'+str(Path(db).resolve())+'?mode=ro',uri=True,timeout=5)
    c.row_factory=sqlite3.Row
    c.execute('pragma query_only=ON')
    return c


def _parse(raw):
    try:return json.loads(raw) if raw else {}
    except ValueError:return {}


def _summary(r):
    return {'id':r['id'],'kind':r['kind'],'label':r['label'],'preview':r['preview'] or '',
            'source_id':r['source_id'],'event_ts':r['event_ts'],'recorded_ts':r['recorded_ts']}


def _get_stats(c):
    stats={k:c.execute('select count(*) from '+k).fetchone()[0] for k in ('nodes','edges','sources')}
    stats['dangling_edges']=c.execute('''select count(*) from edges e left join nodes a on e.src=a.id
    left join nodes b on e.dst=b.id where a.id is null or b.id is null''').fetchone()[0]
    stats['kinds']=[{'kind':k,'count':v} for k,v in c.execute('select kind,count(*) from nodes group by kind order by kind')]
    stats['evidence_states']=[{'state':k,'count':v} for k,v in c.execute('select evidence_state,count(*) from edges group by evidence_state order by count(*) desc')]
    return stats


def _search(c,q):
    terms=q.get('q',[''])[0].strip()
    if len(terms)>250:raise ValueError('Search term too long')
    kinds=q.get('kind',['all'])[0];basis=q.get('basis',['event'])[0]
    year=q.get('year',['all'])[0]
    if basis not in ('event','recorded'):raise ValueError('Time basis must be event or recorded')
    if year not in ('all','unknown') and not re.fullmatch(r'\d{4}',year):raise ValueError('Invalid year')
    lim=_limit(q,'limit',45,200);off=_limit(q,'offset',0,10_000_000)
    cond=[];values=[]
    clauses='FROM nodes n'
    # FTS indexes complete text and supplies a deterministic paginated result.
    tokens=re.findall(r'[^\W_]+',terms,flags=re.UNICODE)
    if terms and not tokens:return {'total':0,'offset':off,'limit':lim,'results':[]}
    if tokens:
        clauses+=' JOIN nodes_fts f ON f.node_id=n.id'
        cond.append('f.nodes_fts MATCH ?')
        values.append(' AND '.join('"'+t.replace('"','""')+'"' for t in tokens))
    if kinds!='all':cond.append('n.kind=?');values.append(kinds)
    tcol='n.event_ts' if basis=='event' else 'n.recorded_ts'
    if year=='unknown':cond.append(tcol+' IS NULL')
    elif year!='all':
        cond.append(tcol+'>=? AND '+tcol+'<?')
        # These bounds reflect UTC calendar years, not guessed local dates.
        import datetime as dt
        values.extend([dt.datetime(int(year),1,1,tzinfo=dt.timezone.utc).timestamp(),
                       dt.datetime(int(year)+1,1,1,tzinfo=dt.timezone.utc).timestamp()])
    where=' WHERE '+' AND '.join(cond) if cond else ''
    total=c.execute('SELECT count(*) '+clauses+where,values).fetchone()[0]
    rows=c.execute('''SELECT n.id,n.kind,n.label,substr(n.body,1,180) AS preview,
       n.source_id,n.event_ts,n.recorded_ts '''+clauses+where+' ORDER BY n.rowid LIMIT ? OFFSET ?',values+[lim,off]).fetchall()
    return {'total':total,'offset':off,'limit':lim,'results':[_summary(x) for x in rows]}


def _node(c,q):
    node_id=q.get('id',[''])[0]
    if not node_id or len(node_id)>500:raise ValueError('Provide a valid node ID')
    size=_limit(q,'body_limit',20000,100000);off=_limit(q,'body_offset',0,2_000_000_000)
    row=c.execute('''SELECT id,kind,label,source_id,event_ts,recorded_ts,metadata_json,layers,
    length(body) AS text_total_chars,substr(body,?,?) AS body FROM nodes WHERE id=?''',(off+1,size,node_id)).fetchone()
    if not row:return None
    result={k:row[k] for k in ('id','kind','label','source_id','event_ts','recorded_ts','text_total_chars','body')}
    result['body_offset']=off;result['body_limit']=size;result['has_more_text']=off+size<result['text_total_chars']
    result['metadata']=_parse(row['metadata_json']);result['layers']=_parse(row['layers'])
    sid=row['source_id']
    if sid:
        sr=c.execute('SELECT id,path,sha256,bytes,mime,parse_status,parent_id,metadata_json FROM sources WHERE id=?',(sid,)).fetchone()
        result['source']=({k:sr[k] for k in ('id','path','sha256','bytes','mime','parse_status','parent_id')}|{'metadata':_parse(sr['metadata_json'])}) if sr else {'reference_id':sid,'registered_source_record':False}
    return result


def _neighbors(c,q):
    node_id=q.get('id',[''])[0]
    if not c.execute('SELECT 1 FROM nodes WHERE id=?',(node_id,)).fetchone():return None
    lim=_limit(q,'limit',60,500);off=_limit(q,'offset',0,10000000)
    total=c.execute('select count(*) from edges where src=? or dst=?',(node_id,node_id)).fetchone()[0]
    rows=c.execute('''SELECT e.id AS edge_id,e.src,e.dst,e.relation,e.source_id AS edge_source,e.evidence_state,e.metadata_json,
         n.id,n.kind,n.label,substr(n.body,1,180) AS preview,n.source_id,n.event_ts,n.recorded_ts
         FROM edges e JOIN nodes n ON n.id=CASE WHEN e.src=? THEN e.dst ELSE e.src END
         WHERE e.src=? OR e.dst=? ORDER BY e.id LIMIT ? OFFSET ?''',(node_id,node_id,node_id,lim,off)).fetchall()
    out=[]
    for r in rows:
        out.append({'direction':'out' if r['src']==node_id else 'in',
                    'node':_summary(r),
                    'edge':{'id':r['edge_id'],'src':r['src'],'dst':r['dst'],'relation':r['relation'],
                            'source_id':r['edge_source'],'evidence_state':r['evidence_state'],
                            'metadata':_parse(r['metadata_json'])}})
    return {'node_id':node_id,'total':total,'offset':off,'limit':lim,'neighbors':out}


def _timeline(c,q):
    basis=q.get('basis',['event'])[0]
    if basis not in ('event','recorded'):raise ValueError('Time basis must be event or recorded')
    col='event_ts' if basis=='event' else 'recorded_ts'
    rows=c.execute('''SELECT CASE WHEN '''+col+''' IS NULL THEN 'Unknown'
          ELSE strftime('%Y','1970-01-01',CAST('''+col+''' AS INTEGER)||' seconds') END year, count(*) AS count
          FROM nodes GROUP BY year ORDER BY year''')
    return {'basis':basis,'years':[{'year':r[0],'count':r[1]} for r in rows]}


def _path(c,q):
    a=q.get('src',[''])[0];z=q.get('dst',[''])[0]
    maxdepth=_limit(q,'depth',5,8)
    if not a or not z:raise ValueError('Provide src and dst node IDs')
    if not c.execute('SELECT 1 FROM nodes WHERE id=?',(a,)).fetchone() or not c.execute('SELECT 1 FROM nodes WHERE id=?',(z,)).fetchone():
        raise ValueError('Unknown graph endpoint')
    if a==z:return {'found':True,'nodes':[a],'edges':[],'truncated':False}
    queue=deque([(a,0)]);visited={a};parents={};truncated=False
    max_visited=12000
    while queue:
        cur,depth=queue.popleft()
        if depth>=maxdepth:continue
        rows=c.execute('''SELECT src,dst,relation,source_id,evidence_state FROM edges
                         WHERE src=? OR dst=? ORDER BY id LIMIT 2001''',(cur,cur)).fetchall()
        if len(rows)>2000:truncated=True
        for e in rows[:2000]:
            next_id=e['dst'] if e['src']==cur else e['src']
            if next_id in visited:continue
            parents[next_id]=(cur,{k:e[k] for k in ('src','dst','relation','source_id','evidence_state')})
            visited.add(next_id)
            if next_id==z:
                ids=[z];es=[];walk=z
                while walk!=a:
                    prev,edge=parents[walk];es.append(edge);ids.append(prev);walk=prev
                return {'found':True,'nodes':list(reversed(ids)),'edges':list(reversed(es)),
                        'truncated':truncated,'visited':len(visited)}
            if len(visited)>=max_visited:
                truncated=True;queue.clear();break
            queue.append((next_id,depth+1))
    return {'found':False,'nodes':[],'edges':[],'truncated':truncated,'visited':len(visited)}


def _sources(c,q):
    lim=_limit(q,'limit',50,300);off=_limit(q,'offset',0,10000000)
    rows=c.execute('SELECT id,path,sha256,bytes,mime,parse_status,parent_id,metadata_json FROM sources ORDER BY path LIMIT ? OFFSET ?',(lim,off)).fetchall()
    return {'total':c.execute('SELECT count(*) FROM sources').fetchone()[0],'offset':off,'limit':lim,
           'results':[{k:r[k] for k in ('id','path','sha256','bytes','mime','parse_status','parent_id')}|{'metadata':_parse(r['metadata_json'])} for r in rows]}


APIS={'/api/stats':lambda c,q:_get_stats(c),'/api/search':_search,'/api/node':_node,
      '/api/neighbors':_neighbors,'/api/timeline':_timeline,'/api/path':_path,'/api/sources':_sources}


def make_server(db_path,token,host='127.0.0.1',port=8765,tls_cert=None,tls_key=None):
    db_path=Path(db_path).resolve()
    if not db_path.exists():raise FileNotFoundError(db_path)
    if not token or len(token)<24:raise ValueError('Use a strong session-access token (>=24 chars)')
    if host not in ('127.0.0.1','localhost','::1') and (not tls_cert or not tls_key):
        raise ValueError('Non-loopback bind requires TLS certificate and private key')
    sessions={}
    class Handler(BaseHTTPRequestHandler):
        server_version='GMRI-Private-Graph/2'
        sys_version=''
        def log_message(self,format,*args):
            # No URL or authentication token is included in logs.
            sys.stderr.write('[GMRI] '+str(self.client_address[0])+' '+format.split(' ')[0]+'\n')
        def _headers(self,status,ctype='application/json; charset=utf-8',size=None,extra=None):
            self.send_response(status)
            self.send_header('Content-Type',ctype)
            self.send_header('Cache-Control','no-store, private')
            self.send_header('X-Content-Type-Options','nosniff')
            self.send_header('X-Frame-Options','DENY')
            self.send_header('Referrer-Policy','no-referrer')
            self.send_header('Content-Security-Policy',CSP)
            if size is not None:self.send_header('Content-Length',str(size))
            for k,v in (extra or {}).items():self.send_header(k,v)
            self.end_headers()
        def _reply(self,status,obj):
            data=json.dumps(obj,ensure_ascii=False,default=str,separators=(',',':')).encode('utf-8')
            self._headers(status,size=len(data));self.wfile.write(data)
        def _authed(self):
            cookie=self.headers.get('Cookie','')
            match=re.search(r'(?:^|;\s*)gmri_session=([^;]+)',cookie)
            t=match.group(1) if match else ''
            expire=sessions.get(t,0)
            if expire and expire>time.monotonic():return True
            if t:sessions.pop(t,None)
            return False
        def do_GET(self):
            parts=urlsplit(self.path);path=parts.path
            if path in MIME:
                name={'/':'explorer.html','/app.js':'app.js','/style.css':'style.css'}[path]
                data=(BASE/name).read_bytes()
                self._headers(200,MIME[path],len(data));self.wfile.write(data);return
            if path not in APIS:
                self._reply(404,{'error':'Not found'});return
            if not self._authed():
                self._reply(401,{'error':'Authentication required'});return
            try:
                with _connect(db_path) as con:
                    r=APIS[path](con,parse_qs(parts.query,keep_blank_values=True))
                if r is None:self._reply(404,{'error':'Record not found'})
                else:self._reply(200,r)
            except (ValueError,sqlite3.OperationalError) as e:
                self._reply(400,{'error':str(e)[:200]})
        def do_POST(self):
            if urlsplit(self.path).path!='/api/login':
                self._reply(404,{'error':'Not found'});return
            try:n=int(self.headers.get('Content-Length','0'))
            except ValueError:n=0
            if n>2048 or n<1:
                self._reply(413,{'error':'Token body length invalid'});return
            try:data=json.loads(self.rfile.read(n))
            except (UnicodeDecodeError,ValueError):data={}
            user_token=data.get('token','')
            if not isinstance(user_token,str) or not hmac.compare_digest(token,user_token):
                self._reply(403,{'error':'Invalid token'});return
            sid=secrets.token_urlsafe(36)
            sessions[sid]=time.monotonic()+43200
            flags='; HttpOnly; SameSite=Strict; Path=/; Max-Age=43200'
            if tls_cert:flags+='; Secure'
            self._reply_with_cookie(sid,flags)
        def _reply_with_cookie(self,sid,flags):
            data=b'{"ok":true}'
            self._headers(200,size=len(data),extra={'Set-Cookie':'gmri_session='+sid+flags})
            self.wfile.write(data)
    s=ThreadingHTTPServer((host,port),Handler)
    if tls_cert:
        context=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        context.load_cert_chain(certfile=tls_cert,keyfile=tls_key)
        s.socket=context.wrap_socket(s.socket,server_side=True)
    return s


def main():
    ap=argparse.ArgumentParser(description='GMRI private 4D graph explorer')
    ap.add_argument('--db',default=str(BASE/'GMRI_universal_stage1.sqlite'))
    ap.add_argument('--host',default='127.0.0.1');ap.add_argument('--port',type=int,default=8765)
    ap.add_argument('--tls-cert');ap.add_argument('--tls-key');ap.add_argument('--token')
    args=ap.parse_args();token=args.token or secrets.token_urlsafe(36)
    s=make_server(args.db,token,args.host,args.port,args.tls_cert,args.tls_key)
    scheme='https' if args.tls_cert else 'http'
    print(f'GMRI private graph explorer ready: {scheme}://{args.host}:{s.server_port}/',flush=True)
    print('ACCESS TOKEN (keep private): '+token,flush=True)
    try:s.serve_forever()
    except KeyboardInterrupt:pass
    finally:s.shutdown();s.server_close()

if __name__=='__main__':main()
