'use strict';
/* Source-preserving client: every viewport is bounded, every database query paginates.
   No user data sent to external hosts; no third-party scripts or analytics. */
const $=id=>document.getElementById(id);
const fmt=n=>Number(n||0).toLocaleString();
const state={view:'graph',query:'',kind:'all',basis:'event',year:'all',offset:0,
  rows:[],total:0,selected:null,node:null,neigh:[],neighOffset:0,neighTotal:0,
  pinnedA:'',pinnedB:'',stats:null,sourceOffset:0,graphPoints:[],graphScale:1,graphPan:[0,0],drag:null};
let searchTimer=null;
function el(tag,className,text){const x=document.createElement(tag);if(className)x.className=className;if(text!==undefined)x.textContent=text;return x}
function clear(node){node.replaceChildren()}
function msg(text){$('statusLine').textContent=text}
function time(ts){return ts===null||ts===undefined?'Unstated':new Date(Number(ts)*1000).toISOString().replace('.000Z','Z')}
function qparams(obj){return Object.entries(obj).filter(([_,v])=>v!==undefined && v!==null).map(([k,v])=>encodeURIComponent(k)+'='+encodeURIComponent(String(v))).join('&')}
async function api(path,params={}){
  const url=path+(Object.keys(params).length?'?'+qparams(params):'');
  const r=await fetch(url,{credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'}});
  let out;try{out=await r.json()}catch(_){out={error:'Invalid server response'}}
  if(!r.ok)throw Error(out.error||('Server returned HTTP '+r.status));
  return out;
}
function mkbutton(label,fn,cls=''){const b=el('button',cls,label);b.type='button';b.addEventListener('click',fn);return b}
async function login(e){e.preventDefault();$('loginError').textContent='';const token=$('token').value;
  try{const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({token})});
    if(!r.ok)throw Error('Token was not accepted.');$('token').value='';await initialize();
  }catch(err){$('loginError').textContent=err.message;}
}
async function initialize(){
  try{state.stats=await api('/api/stats')}
  catch(e){$('loginPanel').hidden=false;$('app').hidden=true;return}
  $('loginPanel').hidden=true;$('app').hidden=false;
  $('statNodes').textContent=fmt(state.stats.nodes);$('statEdges').textContent=fmt(state.stats.edges);$('statSources').textContent=fmt(state.stats.sources);
  populateKinds();await updateYears();await search();setView('graph');msg('Loaded '+fmt(state.stats.nodes)+' records; no content-weighting filter.');
}
function populateKinds(){clear($('kindFilter'));$('kindFilter').append(new Option('All kinds','all'));
  for(const x of state.stats.kinds)$('kindFilter').append(new Option(x.kind+' ('+fmt(x.count)+')',x.kind));
}
async function updateYears(){
  const data=await api('/api/timeline',{basis:state.basis});const year=$('yearFilter');const old=state.year;
  clear(year);year.append(new Option('All years','all'));
  for(const x of data.years){year.append(new Option((x.year==='Unknown'?'Unknown time':x.year)+' ('+fmt(x.count)+')',x.year==='Unknown'?'unknown':x.year))}
  year.value=[...year.options].some(x=>x.value===old)?old:'all';state.year=year.value;
}
async function search(){
  const data=await api('/api/search',{q:state.query,kind:state.kind,year:state.year,basis:state.basis,offset:state.offset,limit:45});
  state.rows=data.results;state.total=data.total;renderResults();
  $('queryCount').textContent=fmt(data.total)+' matching';$('pageMarker').textContent=data.total?fmt(data.offset+1)+'–'+fmt(Math.min(data.offset+data.limit,data.total)):'0';
  $('prevPage').disabled=state.offset<=0;$('nextPage').disabled=state.offset+45>=data.total;
  if(state.view==='graph'&&!state.selected)drawGraph();
}
function renderResults(){const p=$('results');clear(p);
  if(!state.rows.length){p.append(el('div','result','No records match these terms and filters.'));return}
  for(const n of state.rows){const b=el('button','result'+(state.selected===n.id?' active':''));b.type='button';b.setAttribute('role','option');b.setAttribute('aria-selected',String(state.selected===n.id));
    b.append(el('div','smalltype',n.kind));b.append(el('strong','',n.label||n.id));if(n.preview)b.append(el('div','excerpt',n.preview));
    b.addEventListener('click',()=>selectNode(n.id));p.append(b);
  }
}
function refreshFilters(){state.offset=0;search().catch(e=>msg(e.message));if(state.view==='timeline')showTimeline()}
async function selectNode(id){
  if(!id)return;
  state.selected=id;state.neighOffset=0;state.neigh=[];renderResults();
  try{state.node=await api('/api/node',{id,body_limit:20000,body_offset:0});renderInspector();await fetchNeighbors();
    if(state.view==='graph')drawGraph();if(state.view==='mermaid')showMermaid();
  }catch(e){msg('Unable to inspect record: '+e.message)}
}
function renderInspector(){const n=state.node;if(!n)return;
  $('recordTitle').textContent=n.label||n.id;$('selectionKind').textContent=n.kind;
  const m=$('recordMeta');clear(m);for(const [key,value] of Object.entries({ID:n.id,Source:n.source_id||'Unstated',Event:time(n.event_ts),Recorded:time(n.recorded_ts),Layers:(n.layers||[]).join(', ')})){
    const row=el('div');row.append(el('span','',key+': '));row.append(el('code','',value));m.append(row)}
  $('recordBody').textContent=n.body||'(No text extracted; metadata or originals may still exist)';
  $('recordEvidence').textContent=JSON.stringify({record_metadata:n.metadata,source_provenance:n.source||null},null,2);
  $('loadMoreText').hidden=!n.has_more_text;
  for(const id of ['pinA','pinB','showNeighbors','copyBody'])$(id).disabled=false;
}
async function fetchMoreText(){if(!state.node || !state.node.has_more_text)return;
  const n=state.node;const data=await api('/api/node',{id:n.id,body_offset:n.body_offset+n.body.length,body_limit:20000});
  n.body+=data.body;n.has_more_text=data.has_more_text;n.body_limit=n.body.length;$('recordBody').textContent=n.body;$('loadMoreText').hidden=!n.has_more_text;
}
async function fetchNeighbors(){if(!state.selected)return;
  const n=await api('/api/neighbors',{id:state.selected,offset:state.neighOffset,limit:70});
  if(state.neighOffset===0)state.neigh=[];state.neigh.push(...n.neighbors);state.neighTotal=n.total;
  const list=$('neighborList');clear(list);
  for(const k of state.neigh){const b=mkbutton(k.node.label||k.node.id,()=>selectNode(k.node.id));b.prepend(el('div','rel',(k.direction==='out'?'→ ':'← ')+k.edge.relation+' ['+k.edge.evidence_state+']'));list.append(b)}
