#!/usr/bin/env python3
"""Append *all* files under an explicitly supplied local export directory.

Preserves duplicate occurrences and directory topology. A symlink is recorded as
an observable symlink, never followed outside the export. Re-runs are idempotent.
"""
from __future__ import annotations
import argparse,hashlib,json,mimetypes,os
from pathlib import Path
from build_graph import GraphBuilder,stable_id


def index_tree(b:GraphBuilder, root:Path, namespace:str)->dict:
    root=Path(root).resolve(strict=True)
    if not root.is_dir():raise ValueError('Expected an existing directory')
    namespace=str(namespace).strip()
    if not namespace:raise ValueError('A stable import namespace is required')
    totals={'namespace':namespace,'root':str(root),'original_files_registered':0,
            'previously_registered':0,'directories_registered':0,'symlinks_registered':0,
            'errors':[]}
    # os.walk avoids following directory symlinks. It includes hidden entries.
    for base,subdirs,files in os.walk(root,followlinks=False):
        for sub in list(subdirs):
            path=Path(base)/sub
            rel=path.relative_to(root).as_posix()
            if path.is_symlink():
                subdirs.remove(sub)
                _symbol(b,path,namespace,rel);totals['symlinks_registered']+=1
            else:
                nid=stable_id('folder','snapshot',namespace,rel)
                b.node(nid,'directory_record',rel,metadata={'namespace':namespace,'tree_relative_path':rel},layers=['source','junk_drawer'])
                totals['directories_registered']+=1
        for file in sorted(files):
            path=Path(base)/file
            rel=path.relative_to(root).as_posix()
            if path.is_symlink():
                _symbol(b,path,namespace,rel);totals['symlinks_registered']+=1;continue
            src_path=f'snapshot://{namespace}/{rel}'
            try:
                stat=path.stat()
                prior=b.con.execute('SELECT sha256,parse_status,bytes FROM sources WHERE path=?',(src_path,)).fetchone()
                if prior and prior[2]==stat.st_size and prior[1]!='registered':
                    # Recheck content hash only if exact-byte/source integrity is needed;
                    # the fast path here uses both path and size for append-only exports.
                    with open(path,'rb') as f:
                        sha=hashlib.file_digest(f,'sha256').hexdigest()
                    if prior[0]==sha:
                        totals['previously_registered']+=1;continue
                data=path.read_bytes()
                sid=b.source(src_path,data,mimetypes.guess_type(file)[0] or 'application/octet-stream',
                    metadata={'source':'original_local_export_bytes','original_byte_stream_present':True,
                              'namespace':namespace,'relative_path':rel,'mtime_ns':stat.st_mtime_ns})
                if path.suffix.lower()=='.zip':b.ingest_zip(sid,data,src_path)
                else:b.ingest_file_bytes(sid,data,path.name)
                totals['original_files_registered']+=1
            except Exception as exc:
                b.con.execute('insert into events(event_kind,note) values(?,?)',
                    ('local_ingest_error',json.dumps({'namespace':namespace,'relative_path':rel,'error':str(exc)})))
                totals['errors'].append({'path':rel,'error':str(exc)})
            b.con.commit()
    return totals


def _symbol(b,path,namespace,rel):
    try:target=os.readlink(path)
    except OSError:target='UNRESOLVED'
    ident=stable_id('symlink',namespace,rel)
    b.node(ident,'symlink_reference',rel,metadata={'namespace':namespace,'relative_path':rel,'literal_link_target':target,
          'followed':False},layers=['source','junk_drawer'])


def main():
    ap=argparse.ArgumentParser(description='Ingest all local files in a source export tree, retaining each occurrence')
    ap.add_argument('--directory',required=True,type=Path,help='The original source export root')
    ap.add_argument('--namespace',required=True,help='Stable name: e.g. library-export-2026-10-28')
    ap.add_argument('--db',type=Path,default=Path(__file__).resolve().parent/'GMRI_universal_stage1.sqlite')
    opts=ap.parse_args();b=GraphBuilder(opts.db)
    try:
        result=index_tree(b,opts.directory,opts.namespace);b.close()
        print(json.dumps(result,indent=2))
        if result['errors']:raise SystemExit('Import logged errors; review results before accepting completeness')
    finally:
        try:b.con.close()
        except Exception:pass


if __name__=='__main__':main()
