import { PersonalityCore } from './personality_core';
import { DialogueManager } from './dialogue_manager';
import { EmotionalIntelligence } from './emotional_intelligence';
import { AdaptiveLearning } from './adaptive_learning';
import { MemoryBank } from './memory_bank';
import { BehaviorModel } from './behavior_model';

export interface PersonalityTrait {
    confidence: number;
    wit: number;
    intellect: number;
    charm: number;
    emotionalDepth: number;
}

export type Behavior = 'aggressive' | 'friendly' | 'neutral' | 'casual' | 'serious' | 'playful' | 'sarcastic';

export interface Emotion {
    type: 'happy' | 'sad' | 'angry' | 'neutral';
    intensity: number;
}

export class TonyStarkAICore {
    private personalityCore: PersonalityCore;
    private dialogueManager: DialogueManager;
    private behaviorModel: BehaviorModel;
    private emotionalIntelligence: EmotionalIntelligence;
    private adaptiveLearning: AdaptiveLearning;
    private memoryBank: MemoryBank;

    constructor() {
        this.personalityCore = new PersonalityCore();
        this.dialogueManager = new DialogueManager();
        this.emotionalIntelligence = new EmotionalIntelligence();
        this.adaptiveLearning = new AdaptiveLearning();
        this.behaviorModel = new BehaviorModel();
        this.memoryBank = new MemoryBank();
    }

    processInput(input: string): string {
        const emotion = this.emotionalIntelligence.analyzeEmotion(input);
        const context = this.adaptiveLearning.getContext(input);
        const relevantMemories = this.memoryBank.retrieveRelevantMemories(input);

        const baseResponse = this.dialogueManager.generateResponse(input, emotion, context, relevantMemories);
        const behavior = this.behaviorModel.determineBehavior(baseResponse, emotion);
        const personalizedResponse = this.personalityCore.applyPersonality(baseResponse, behavior);

        this.memoryBank.storeInteraction(input, personalizedResponse);

        return this.addNonverbalCues(personalizedResponse, behavior);
    }

    private addNonverbalCues(response: string, behavior: Behavior): string {
        const cues = this.behaviorModel.generateNonverbalCues(behavior);
        return `${cues.before} ${response} ${cues.after}`;
    }
}
