   const remainder=rels.filter(e=>!e[4].startsWith('reason:'));
   for(const e of [...preferred,...remainder].slice(0,110)){
    edgeMap.set(e[4],e);for(const n of [e[0],e[1]])if(!seen.has(n)&&seen.size<cap){seen.add(n);next.push(n)}
